"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def unnamed_function(arr, target):
    seen = {}
    pairs = []
    for num in arr:
        comp = (target - num)
        if (comp in seen):
            pairs.append((min(num, comp), max(num, comp)))
        seen[num] = True
    return set(pairs)
print(unnamed_function([1, 7, -4.55, -4, 0], 3))
print(unnamed_function([1, 7, -4.55, 7, 3], 10))